    var prev *Node
    curr := head
    for curr != nil {
        next := curr.Next // guarda el siguiente
        curr.Next = prev  // invierte el enlace
        prev = curr       // avanza prev
        curr = next       // avanza curr
    }
    return prev // nueva cabeza
}

func main() {
    // 1 -> 2 -> 3
    head := &Node{1, &Node{2, &Node{3, nil}}}

    head = Reverse(head)

    for n := head; n != nil; n = n.Next {
        fmt.Print(n.Val, " ")
    }
    // Salida: 3 2 1
}
```

## Cómo funciona

Estado inicial: `prev = nil`, `curr = 1`.

| Paso | curr | Acción | Lista resultante |
|------|------|--------|------------------|
| 1 | 1 | `1.Next = nil` | `nil <- 1`, resto: `2 -> 3` |
| 2 | 2 | `2.Next = 1` | `nil <- 1 <- 2`, resto: `3` |
| 3 | 3 | `3.Next = 2` | `nil <- 1 <- 2 <- 3` |

Al terminar, `curr` es `nil` y `prev` apunta al último nodo, que ahora es la cabeza.

## Versión recursiva (O(n) tiempo, O(n) pila)

```go
func ReverseRec(head *Node) *Node {
    if head == nil || head.Next == nil {
        return head
    }
    newHead := ReverseRec(head.Next)
    head.Next.Next = head // el siguiente apunta de vuelta a head
    head.Next = nil       // head pasa a ser el final
    return newHead
}
```

## Notas

- Si la lista está vacía (`head == nil`), ambas versiones devuelven `nil`, sin caso especial.
- Debes reasignar la cabeza (`head = Reverse(head)`), porque la antigua pasa a ser la cola.
- Prefiere la iterativa: no consume pila y no corre riesgo de desbordamiento con listas muy largas.
